def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    dangerous_count = 0
    eric_like_pressure = 0.0
    cindy_like_pressure = 0.0

    for opp in alive:
        prev = opp.get('previous_trace', {})
        b = None
        if prev:
            b = prev.get('bid')
        if b is not None:
            prev_bids.append(float(b))
            if b >= 120:
                dangerous_count += 1
            req = opp.get('water_requirement', WATER_REQ)
            sal = opp.get('daily_salary', DAILY_SALARY)
            if req >= 13 and sal >= 70:
                if b > eric_like_pressure:
                    eric_like_pressure = float(b)
            else:
                if b > cindy_like_pressure:
                    cindy_like_pressure = float(b)

    highest_prev = max(prev_bids) if prev_bids else 0.0

    supply_ratio = (float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    elif hp <= 6:
        urgency += 0.25

    if no_water_days >= 2:
        urgency += 0.9
    elif no_water_days >= 1:
        urgency += 0.35

    scarcity = 1.0 - supply_ratio

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 4.0)
    else:
        if scarcity >= 0.75:
            target = max(92.0, highest_prev * 0.78 + 8.0)
        elif scarcity >= 0.45:
            target = max(68.0, highest_prev * 0.62 + 5.0)
        else:
            target = max(36.0, highest_prev * 0.38 + 2.0)

        if dangerous_count >= 2:
            target *= 0.92
        elif eric_like_pressure >= 150 and hp > 4 and no_water_days == 0 and scarcity < 0.6:
            target *= 0.72

        if cindy_like_pressure >= 100 and scarcity >= 0.45:
            target += 6.0

        target += urgency * 18.0

        reserve = 0.0
        if day <= 3:
            reserve = 35.0
        elif day <= 6:
            reserve = 20.0
        else:
            reserve = 8.0

        max_safe = budget - reserve
        if max_safe < DAILY_SALARY * 0.25:
            max_safe = budget

        bid = min(target, max_safe)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    min_defensive = 0.0
    if hp <= 4 or no_water_days >= 1:
        min_defensive = DAILY_SALARY * 0.55
    if bid < min_defensive and budget >= min_defensive:
        bid = min_defensive

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Urgency: if we've already gone without water, increase pressure.
    urgency = 0.0
    if no_water_days >= 2:
        urgency = 1.0
    elif no_water_days == 1:
        urgency = 0.6

    base_cap = DAILY_SALARY * 0.65  # conservative default

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

        # If someone previously bid extremely high (Cindy/Eric), we don't match fully.
        if highest_prev_bid >= DAILY_SALARY * 1.4:  # ~126
            # Bid enough to avoid being the one starved, but keep budget.
            target = DAILY_SALARY * 0.72 + urgency * DAILY_SALARY * 0.18
        elif highest_prev_bid >= DAILY_SALARY * 0.9:  # ~81
            target = max(DAILY_SALARY * 0.55, second_prev_bid * 0.55) + urgency * DAILY_SALARY * 0.15
        else:
            # If bids were low, we can secure water with a moderate bet.
            target = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.85) + urgency * DAILY_SALARY * 0.10
    else:
        target = base_cap + urgency * DAILY_SALARY * 0.20

    # If our hp is low, we must bid more aggressively.
    if hp <= 2:
        target = max(target, DAILY_SALARY * 0.9)
    elif hp <= 4:
        target = max(target, DAILY_SALARY * 0.75)

    # Supply scaling: higher supply means we can bid less.
    # supply in [15,25]
    if supply <= MIN_SUPPLY + 1e-9:
        supply_factor = 1.0
    elif supply >= MAX_SUPPLY - 1e-9:
        supply_factor = 0.75
    else:
        supply_factor = 1.0 - 0.25 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    target = target * supply_factor

    # Final clamp to budget.
    if budget <= 0:
        return 0.0
    bid = min(budget, target)

    # Avoid bidding 0 when we still need water soon.
    if bid <= 0 and no_water_days >= 1:
        bid = min(budget, DAILY_SALARY * 0.6)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.5 # 75

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # Aggressive bidding if HP is critically low
        if my_status['hp'] <= 3:
            return min(my_status['budget'], DAILY_SALARY * 0.95)

        # If highest previous bid was very high, react
        if highest_prev_bid >= DAILY_SALARY * 0.8: # Threshold of 120
            # If my HP is good, try to conserve but stay competitive
            if my_status['hp'] > 5:
                return min(my_status['budget'], max(base_bid, highest_prev_bid * 0.95))
            else: # HP is getting lower, must be more aggressive
                return min(my_status['budget'], highest_prev_bid + 5)

        # If highest previous bid was moderate
        else:
            return min(my_status['budget'], max(base_bid, highest_prev_bid + 2))

    # If no previous bids from opponents (e.g., first day or opponents died without bidding)
    # or if the above conditions didn't trigger, use HP-based strategy
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    elif my_status['hp'] <= 5:
        return min(my_status['budget'], DAILY_SALARY * 0.7)
    else:
        return min(my_status['budget'], base_bid)

